func NewGormRepository(db *gorm.DB) *GormRepository {
	return &GormRepository{db: db}
}

func (r *GormRepository) Create(ctx context.Context, org *domain.Entity) error {
	model := toModel(org)
	if err := r.db.WithContext(ctx).Create(&model).Error; err != nil {
		return err
	}
	org.ID = model.ID
	return nil
}

func (r *GormRepository) CreateWithOwner(ctx context.Context, org *domain.Entity, ownerUserID uint) (*domain.OwnerEmployeeRow, error) {
	var createdEmployee domain.OwnerEmployeeRow
	err := r.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		model := toModel(org)
		if err := tx.Create(&model).Error; err != nil {
			return err
		}

		org.ID = model.ID

		employee := models.Employee{
			UserID:         ownerUserID,
			OrganisationID: model.ID,
			EmploymentID:   int(model.ID),
			Type:           "owner",
			LastLoginAt:    time.Now().UTC(),
		}

		if err := tx.Create(&employee).Error; err != nil {
			return err
		}

		if err := tx.Model(&models.Organisation{}).Where("id = ?", model.ID).Update("boss_id", ownerUserID).Error; err != nil {
			return err
		}

		org.BossID = ownerUserID
		org.ID = model.ID
		org.PlanID = model.PlanID
		org.PlanStartDate = model.PlanStartDate
		org.PlanEndDate = model.PlanEndDate
		org.PlanStatus = model.PlanStatus
		org.MaxEmployees = model.MaxEmployees
		org.CompanyLogo = model.CompanyLogo
		org.Industry = model.Industry
		org.BillingAddress = model.BillingAddress
		org.CompanySize = model.CompanySize

		createdEmployee = domain.OwnerEmployeeRow{
			UserID:         employee.UserID,
