			OrganisationID: employee.OrganisationID,
			Type:           employee.Type,
			Salary:         employee.Salary,
			LastLoginAt:    employee.LastLoginAt,
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	return &createdEmployee, nil
}

