	req.ID = uint(id)

	err = h.uc.Update(c.Request.Context(), req, userID, role, orgID)
	if err != nil {
		if err == domain.ErrUnauthorized {
			c.JSON(http.StatusForbidden, gin.H{"error": "Forbidden"})
			return
		}
		if err == domain.ErrNotFound {
