package task_attachments

import (
	"context"
	"server/internal/domain/task_attachments"
	"time"
)

type service struct {
	repo task_attachments.Repository
}

func NewService(repo task_attachments.Repository) task_attachments.UseCase {
	return &service{repo: repo}
}

func (s *service) AttachFile(ctx context.Context, taskID uint, fileID uint, uploadedBy uint, fileName string) (*task_attachments.TaskAttachment, error) {
	attachment := &task_attachments.TaskAttachment{
		TaskID:     taskID,
		FileID:     fileID,
		UploadedBy: uploadedBy,
		FileName:   fileName,
		CreatedAt:  time.Now(),
	}

	if err := s.repo.Create(ctx, attachment); err != nil {
		return nil, err
	}

	return attachment, nil
}

func (s *service) GetAttachments(ctx context.Context, taskID uint) ([]task_attachments.TaskAttachment, error) {
	return s.repo.GetByTaskID(ctx, taskID)
}

func (s *service) RemoveAttachment(ctx context.Context, attachmentID uint, requestingUserID uint) error {
	attachment, err := s.repo.GetByID(ctx, attachmentID)
	if err != nil {
		return err
	}
	if attachment == nil {
		return task_attachments.ErrAttachmentNotFound
	}

	if attachment.UploadedBy != requestingUserID {
		return task_attachments.ErrNotAttachmentOwner
	}

	return s.repo.Delete(ctx, attachmentID)
}

3653078bcb5edd47813a145595ffb35c.content:
package chats

import (
	"context"
	"fmt"
	domain "server/internal/domain/chats"
	"server/internal/platform/database/models"
	"time"

	"gorm.io/gorm"
	"gorm.io/gorm/clause"
)

type GormRepository struct{ db *gorm.DB }

func NewGormRepository(db *gorm.DB) *GormRepository { return &GormRepository{db: db} }

func toDomainChat(row models.Chat, participants []models.ChatParticipant) domain.Chat {
	var parts []domain.ChatParticipant
	for _, p := range participants {
		parts = append(parts, domain.ChatParticipant{
			ChatID:            p.ChatID,
			UserID:            p.UserID,
			UnreadCount:       p.UnreadCount,
			LastReadMessageID: p.LastReadMessageID,
			JoinedAt:          p.JoinedAt,
		})
	}
	var createdBy uint
	if row.CreatedBy != nil {
		createdBy = *row.CreatedBy
	}

	return domain.Chat{
		ID:             row.ID,
		RoomID:         row.RoomID,
		OrganisationID: row.OrganisationID,
		Name:           row.Name,
		IsGroup:        row.IsGroup,
		CreatedBy:      createdBy,
		LastMessage:    row.LastMessage,
		LastMessageAt:  row.LastMessageAt,
		MessageCount:   row.MessageCount,
		Participants:   parts,
		CreatedAt:      row.CreatedAt,
		UpdatedAt:      row.UpdatedAt,
	}
}

func (r *GormRepository) Create(ctx context.Context, chat *domain.Chat) error {
	var createdBy *uint
	if chat.CreatedBy > 0 {
		createdBy = &chat.CreatedBy
	}
	m := models.Chat{
		RoomID:         chat.RoomID,
		OrganisationID: chat.OrganisationID,
		Name:           chat.Name,
		IsGroup:        chat.IsGroup,
		CreatedBy:      createdBy,
		LastMessage:    chat.LastMessage,
		LastMessageAt:  chat.LastMessageAt,
		MessageCount:   chat.MessageCount,
	}
	if err := r.db.WithContext(ctx).Create(&m).Error; err != nil {
		return err
	}
	chat.ID = m.ID
	chat.CreatedAt = m.CreatedAt
	chat.UpdatedAt = m.UpdatedAt

	// If it's a group and RoomID wasn't set, set it now
	if chat.IsGroup && chat.RoomID == "" {
		chat.RoomID = fmt.Sprintf("group_%d", chat.ID)
		r.db.WithContext(ctx).Model(&m).Update("room_id", chat.RoomID)
	}

	// Insert participants
	for i, p := range chat.Participants {
		pModel := models.ChatParticipant{
			ChatID:      m.ID,
			UserID:      p.UserID,
			UnreadCount: p.UnreadCount,
		}
		if err := r.db.WithContext(ctx).Create(&pModel).Error; err != nil {
			return err
		}
		chat.Participants[i].ChatID = m.ID
		chat.Participants[i].JoinedAt = pModel.JoinedAt
	}

	return nil
}

func (r *GormRepository) ListByOrganisation(ctx context.Context, organisationID uint) ([]domain.Chat, error) {
	var rows []models.Chat
	if err := r.db.WithContext(ctx).Where("organisation_id = ?", organisationID).Order("last_message_at desc nulls last").Find(&rows).Error; err != nil {
		return nil, err
	}

	// Preload participants manually (or could use gorm preload if we define relations, but we don't have explicit relations in models currently)
	var chatIDs []uint
	for _, row := range rows {
		chatIDs = append(chatIDs, row.ID)
	}

	var allParticipants []models.ChatParticipant
	if len(chatIDs) > 0 {
		r.db.WithContext(ctx).Where("chat_id IN ?", chatIDs).Find(&allParticipants)
	}

	partMap := make(map[uint][]models.ChatParticipant)
	for _, p := range allParticipants {
		partMap[p.ChatID] = append(partMap[p.ChatID], p)
	}

	var out []domain.Chat
	for _, row := range rows {
		out = append(out, toDomainChat(row, partMap[row.ID]))
	}
	return out, nil
}

func (r *GormRepository) ListByUser(ctx context.Context, userID uint, orgID uint) ([]domain.Chat, error) {
	// Auto-create DMs with all employees in the org
	var employees []models.Employee
	if err := r.db.WithContext(ctx).Where("organisation_id = ?", orgID).Find(&employees).Error; err == nil {
		for _, emp := range employees {
			if emp.UserID != userID && emp.UserID != 0 {
				_, _ = r.GetOrCreateDM(ctx, userID, emp.UserID, orgID)
			}
		}
	}

	var participants []models.ChatParticipant
	if err := r.db.WithContext(ctx).Where("user_id = ?", userID).Find(&participants).Error; err != nil {
		return nil, err
	}

	var chatIDs []uint
	for _, p := range participants {
		chatIDs = append(chatIDs, p.ChatID)
	}

	if len(chatIDs) == 0 {
		return []domain.Chat{}, nil
	}

	var rows []models.Chat
	if err := r.db.WithContext(ctx).Where("id IN ? AND organisation_id = ?", chatIDs, orgID).Order("last_message_at desc nulls last").Find(&rows).Error; err != nil {
		return nil, err
	}

	// fetch all participants for these chats
	var allParticipants []models.ChatParticipant
	if err := r.db.WithContext(ctx).Where("chat_id IN ?", chatIDs).Find(&allParticipants).Error; err == nil {
		// Also fetch user details to populate FirstName, LastName, AvatarURL
		var userIDs []uint
		for _, p := range allParticipants {
			userIDs = append(userIDs, p.UserID)
		}

		var users []models.UserModel
		if len(userIDs) > 0 {
			r.db.WithContext(ctx).Where("id IN ?", userIDs).Find(&users)
		}
		userMap := make(map[uint]models.UserModel)
		for _, u := range users {
			userMap[u.ID] = u
		}

		partMap := make(map[uint][]domain.ChatParticipant)
		for _, p := range allParticipants {
			dp := domain.ChatParticipant{
				ChatID:            p.ChatID,
				UserID:            p.UserID,
				UnreadCount:       p.UnreadCount,
				LastReadMessageID: p.LastReadMessageID,
				JoinedAt:          p.JoinedAt,
			}
			if u, ok := userMap[p.UserID]; ok {
				dp.FirstName = u.FirstName
				dp.LastName = u.LastName
				dp.AvatarURL = u.ProfilePic
			}
			partMap[p.ChatID] = append(partMap[p.ChatID], dp)
		}

		var out []domain.Chat
		for _, row := range rows {
			chat := toDomainChat(row, nil)
			chat.Participants = partMap[row.ID]

			// Auto name DM
			if !chat.IsGroup && len(chat.Participants) == 2 {
				for _, p := range chat.Participants {
					if p.UserID != userID {
						chat.Name = fmt.Sprintf("%s %s", p.FirstName, p.LastName)
						break
					}
				}
			}

			out = append(out, chat)
		}
		return out, nil
	}

	return nil, nil
}

func (r *GormRepository) GetByID(ctx context.Context, chatID uint) (*domain.Chat, error) {
	var row models.Chat
	if err := r.db.WithContext(ctx).First(&row, chatID).Error; err != nil {
		return nil, err
	}

	var parts []models.ChatParticipant
	r.db.WithContext(ctx).Where("chat_id = ?", chatID).Find(&parts)

	chat := toDomainChat(row, parts)
	return &chat, nil
}

func (r *GormRepository) GetByRoomID(ctx context.Context, roomID string) (*domain.Chat, error) {
	var row models.Chat
	if err := r.db.WithContext(ctx).Where("room_id = ?", roomID).First(&row).Error; err != nil {
		return nil, err
	}

	var parts []models.ChatParticipant
	r.db.WithContext(ctx).Where("chat_id = ?", row.ID).Find(&parts)

	chat := toDomainChat(row, parts)
	return &chat, nil
}

func (r *GormRepository) UpdateLastMessage(ctx context.Context, id uint, message string, at *string) error {
	var ts *time.Time
	if at != nil && *at != "" {
		parsed, err := time.Parse(time.RFC3339, *at)
		if err == nil {
			ts = &parsed
		}
	}
	updates := map[string]any{"last_message": message, "last_message_at": ts}
	return r.db.WithContext(ctx).Model(&models.Chat{}).Where("id = ?", id).Updates(updates).Error
}

func (r *GormRepository) IncrementMessageCount(ctx context.Context, id uint) error {
	return r.db.WithContext(ctx).Model(&models.Chat{}).Where("id = ?", id).UpdateColumn("message_count", gorm.Expr("message_count + 1")).Error
}

func (r *GormRepository) GetOrCreateDM(ctx context.Context, userA uint, userB uint, orgID uint) (*domain.Chat, error) {
	// Find existing DM between userA and userB
	var chatID uint

	// Query to find a chat where both participants exist AND IsGroup = false
	err := r.db.WithContext(ctx).Raw(`
		SELECT c.id FROM chats c
		JOIN chat_participants p1 ON c.id = p1.chat_id
		JOIN chat_participants p2 ON c.id = p2.chat_id
		WHERE c.is_group = false AND c.organisation_id = ?
		AND p1.user_id = ? AND p2.user_id = ?
	`, orgID, userA, userB).Scan(&chatID).Error

	if err != nil || chatID == 0 {
		var smaller, larger uint
		if userA < userB {
			smaller = userA
			larger = userB
		} else {
			smaller = userB
			larger = userA
		}
		roomID := fmt.Sprintf("dm_%d_%d", smaller, larger)

		// create new DM
		chat := &domain.Chat{
			RoomID:         roomID,
			OrganisationID: orgID,
			IsGroup:        false,
			Participants: []domain.ChatParticipant{
				{UserID: userA},
				{UserID: userB},
			},
		}
		if err := r.Create(ctx, chat); err != nil {
			return nil, err
		}
		return r.GetByID(ctx, chat.ID)
	}

	return r.GetByID(ctx, chatID)
}

func (r *GormRepository) AddParticipant(ctx context.Context, chatID uint, userID uint) error {
	p := models.ChatParticipant{
		ChatID: chatID,
		UserID: userID,
	}
	return r.db.WithContext(ctx).Clauses(clause.OnConflict{DoNothing: true}).Create(&p).Error
}

func (r *GormRepository) UpdateUnreadCount(ctx context.Context, chatID uint, userID uint, delta int) error {
	if delta > 0 {
		return r.db.WithContext(ctx).Model(&models.ChatParticipant{}).
			Where("chat_id = ? AND user_id = ?", chatID, userID).
			UpdateColumn("unread_count", gorm.Expr("unread_count + ?", delta)).Error
	}
	return nil
}

func (r *GormRepository) ResetUnreadCount(ctx context.Context, chatID uint, userID uint) error {
	return r.db.WithContext(ctx).Model(&models.ChatParticipant{}).
		Where("chat_id = ? AND user_id = ?", chatID, userID).
		Update("unread_count", 0).Error
}

func (r *GormRepository) GetParticipants(ctx context.Context, chatID uint) ([]domain.ChatParticipant, error) {
	var parts []models.ChatParticipant
	if err := r.db.WithContext(ctx).Where("chat_id = ?", chatID).Find(&parts).Error; err != nil {
		return nil, err
	}
	var out []domain.ChatParticipant
	for _, p := range parts {
		out = append(out, domain.ChatParticipant{
			ChatID:            p.ChatID,
			UserID:            p.UserID,
			UnreadCount:       p.UnreadCount,
			LastReadMessageID: p.LastReadMessageID,
			JoinedAt:          p.JoinedAt,
		})
	}
	return out, nil
}

379c2baaec5f3924937979e7de4ecf51.content:
package analytics

import (
	"context"
	authDomain "server/internal/domain/auth"
	"server/internal/domain/analytics"
	"server/internal/domain/employees"
	orgDomain "server/internal/domain/organisation"
	"server/internal/platform/database/models"
	"time"

	"gorm.io/gorm"
)

type gormRepository struct {
	db *gorm.DB
}

func NewGormRepository(db *gorm.DB) analytics.Repository {
	return &gormRepository{db: db}
}

func (r *gormRepository) GetEmployeeAnalytics(ctx context.Context, userID uint, orgID uint, period string) (*analytics.EmployeeAnalyticsSummary, error) {
	// Parse period to get the start date
	now := time.Now()
	var startDate time.Time
	switch period {
	case "week":
		startDate = now.AddDate(0, 0, -7)
	case "quarter":
		startDate = now.AddDate(0, -3, 0)
	case "month":
		fallthrough
	default:
		startDate = now.AddDate(0, -1, 0)
	}
	startDateStr := startDate.Format("2006-01-02")

	// 1. Get Employee Info
	var empModel models.Employee
	if err := r.db.WithContext(ctx).Where("user_id = ? AND organisation_id = ?", userID, orgID).Preload("User").First(&empModel).Error; err != nil {
		return nil, err
	}

	emp := toEmployeeDomain(&empModel)

	summary := &analytics.EmployeeAnalyticsSummary{
		EmployeeInfo: emp,
		Attendance:   analytics.AnalyticsAttendanceBlock{},
		Leave: analytics.AnalyticsLeaveBlock{
			LeavesByType: make(map[string]int),
		},
		Tasks: analytics.AnalyticsTaskBlock{},
	}

	// 2. Aggregate Attendance
	type AttendanceStats struct {
		PresentDays          int
		TotalDurationMinutes int
		LateCheckins         int
	}
	var attStats AttendanceStats
	r.db.WithContext(ctx).Table("attendances").
		Select("COUNT(id) as present_days").
		Where("user_id = ? AND date >= ?", userID, startDateStr).
		Scan(&attStats.PresentDays)

	// Since SQLite doesn't natively have easy date diff for duration in minutes without some function,
	// let's do it via rows and calculate in memory for duration and late checkins
	rows, err := r.db.WithContext(ctx).Table("attendances").
		Select("check_in_time, check_out_time").
		Where("user_id = ? AND date >= ?", userID, startDateStr).
		Rows()

	if err == nil {
		defer rows.Close()
		var checkInTime, checkOutTime *time.Time
		var totalCheckInMinutes int
		for rows.Next() {
			rows.Scan(&checkInTime, &checkOutTime)
			if checkInTime != nil && checkOutTime != nil {
				attStats.TotalDurationMinutes += int(checkOutTime.Sub(*checkInTime).Minutes())
			}
			if checkInTime != nil {
				totalCheckInMinutes += checkInTime.Hour()*60 + checkInTime.Minute()
				if checkInTime.Hour() > 9 || (checkInTime.Hour() == 9 && checkInTime.Minute() > 30) {
					attStats.LateCheckins++
				}
			}
		}

		summary.Attendance.PresentDays = attStats.PresentDays
		summary.Attendance.TotalWorkingDays = int(now.Sub(startDate).Hours() / 24)
		summary.Attendance.AbsentDays = summary.Attendance.TotalWorkingDays - attStats.PresentDays
		if summary.Attendance.AbsentDays < 0 {
			summary.Attendance.AbsentDays = 0
		}

		if summary.Attendance.TotalWorkingDays > 0 {
			summary.Attendance.AttendanceRate = float64(attStats.PresentDays) / float64(summary.Attendance.TotalWorkingDays) * 100
		}
		if attStats.PresentDays > 0 {
			summary.Attendance.AverageDurationMinutes = attStats.TotalDurationMinutes / attStats.PresentDays

			avgCheckInMins := totalCheckInMinutes / attStats.PresentDays
			avgTime := time.Date(0, 1, 1, avgCheckInMins/60, avgCheckInMins%60, 0, 0, time.UTC)
			summary.Attendance.AverageCheckInTime = avgTime.Format("03:04 PM")
		}
		summary.Attendance.LateCheckins = attStats.LateCheckins
	}

	// 3. Aggregate Leaves
	leaveRows, err := r.db.WithContext(ctx).Table("leaves").
		Select("status, total_days, leave_type").
		Where("employee_id = ? AND start_date >= ?", userID, startDateStr).
		Rows()

	if err == nil {
		defer leaveRows.Close()
		var status string
		var totalDays int
		var leaveType string
		for leaveRows.Next() {
			leaveRows.Scan(&status, &totalDays, &leaveType)
			summary.Leave.TotalLeavesInPeriod += totalDays
			if status == "approved" {
				summary.Leave.Approved++
			} else if status == "pending" {
				summary.Leave.Pending++
			} else if status == "rejected" {
				summary.Leave.Rejected++
			}
			summary.Leave.LeavesByType[leaveType]++
		}
	}

	// 4. Aggregate Tasks
	type TaskStats struct {
		Status string
		Count  int
	}
	// For Tasks, they might be in `tasks` table or similar, assuming standard structure.
	// We check `tasks` table. But actually the `tasks` table is usually linked via `task_assignees` or `assigned_to`
	taskRows, err := r.db.WithContext(ctx).Table("tasks").
		Select("status, count(id) as count").
		Where("assigned_to = ? AND created_at >= ?", userID, startDate).
		Group("status").
		Rows()
	if err == nil {
		defer taskRows.Close()
		var status string
		var count int
		for taskRows.Next() {
			taskRows.Scan(&status, &count)
			summary.Tasks.TotalAssigned += count
			if status == "completed" {
				summary.Tasks.Completed += count
			} else if status == "in_progress" || status == "todo" {
				summary.Tasks.InProgress += count
			}
		}

		// Get overdue tasks
		var overdueCount int
		r.db.WithContext(ctx).Table("tasks").
			Where("assigned_to = ? AND due_date < ? AND status != 'completed'", userID, now).
			Select("count(id)").
			Scan(&overdueCount)

		summary.Tasks.Overdue = overdueCount
		if summary.Tasks.TotalAssigned > 0 {
			summary.Tasks.CompletionRate = float64(summary.Tasks.Completed) / float64(summary.Tasks.TotalAssigned) * 100
		}
	}

	return summary, nil
}

func (r *gormRepository) GetOrgEmployeeMonitor(ctx context.Context, orgID uint) ([]analytics.EmployeeMonitorResponse, error) {
	var modelsList []models.Employee
	if err := r.db.WithContext(ctx).Preload("User").Where("organisation_id = ?", orgID).Find(&modelsList).Error; err != nil {
		return nil, err
	}

	var employeesList []employees.Employee
	for _, m := range modelsList {
		employeesList = append(employeesList, toEmployeeDomain(&m))
	}

	var responses []analytics.EmployeeMonitorResponse

	now := time.Now()
	startDateStr := now.AddDate(0, -1, 0).Format("2006-01-02")
	totalWorkingDays := int(now.Sub(now.AddDate(0, -1, 0)).Hours() / 24)

	for _, emp := range employeesList {
		snap := analytics.EmployeeMonitorSnapshot{
			LastSeen: &emp.LastLoginAt,
		}

		// Calculate Attendance Rate this month
		var presentDays int
		r.db.WithContext(ctx).Table("attendances").
			Where("user_id = ? AND date >= ?", emp.UserID, startDateStr).
			Select("COUNT(id)").
			Scan(&presentDays)
		if totalWorkingDays > 0 {
			snap.AttendanceRateThisMonth = float64(presentDays) / float64(totalWorkingDays) * 100
		}

		// Calculate Pending leaves
		r.db.WithContext(ctx).Table("leaves").
			Where("employee_id = ? AND status = 'pending'", emp.UserID).
			Select("COUNT(id)").
			Scan(&snap.LeavesPending)

		// Calculate Overdue tasks
		r.db.WithContext(ctx).Table("tasks").
			Where("assigned_to = ? AND due_date < ? AND status != 'completed'", emp.UserID, now).
			Select("COUNT(id)").
			Scan(&snap.TasksOverdue)

		// Determine status
		snap.Status = "inactive"
		if !emp.LastLoginAt.IsZero() {
			daysSinceLogin := now.Sub(emp.LastLoginAt).Hours() / 24
			if daysSinceLogin <= 7 {
				snap.Status = "active"
			} else if daysSinceLogin <= 30 {
				snap.Status = "idle"
			}
		}

		responses = append(responses, analytics.EmployeeMonitorResponse{
			EmployeeInfo: emp,
			Snapshot:     snap,
		})
	}

	return responses, nil
}

func toEmployeeDomain(m *models.Employee) employees.Employee {
	return employees.Employee{
		UserID: m.UserID,
		User: authDomain.User{
			ID:          m.User.ID,
			FirstName:   m.User.FirstName,
			LastName:    m.User.LastName,
			Email:       m.User.Email,
			PhoneNumber: m.User.PhoneNumber,
		},
		EmploymentID:   m.EmploymentID,
		OrganisationID: m.OrganisationID,
		Organisation: orgDomain.Entity{
			ID:          m.Organisation.ID,
			CompanyName: m.Organisation.CompanyName,
		},
		Email:       m.Email,
		Type:        m.Type,
		Salary:      m.Salary,
		LastLoginAt: m.LastLoginAt,
	}
}

